package solution

import (
	"fmt"
	"reflect"
	"sort"
)

type MethodSignature struct {
	Name    string
	Inputs  []reflect.Type
	Outputs []reflect.Type
}

func receiverValue(receiver any) (reflect.Value, error) {
	if receiver == nil {
		return reflect.Value{}, fmt.Errorf("nil receiver")
	}
	value := reflect.ValueOf(receiver)
	if value.Kind() == reflect.Ptr && value.IsNil() {
		return reflect.Value{}, fmt.Errorf("nil receiver")
	}
	return value, nil
}

func ListCallable(receiver any) ([]MethodSignature, error) {
	value, err := receiverValue(receiver)
	if err != nil {
		return nil, err
	}
	typ := value.Type()
	out := make([]MethodSignature, 0, typ.NumMethod())
	for i := 0; i < typ.NumMethod(); i++ {
		method := typ.Method(i)
		bound := value.MethodByName(method.Name).Type()
		inputs := make([]reflect.Type, bound.NumIn())
		for j := range inputs {
			inputs[j] = bound.In(j)
		}
		outputs := make([]reflect.Type, bound.NumOut())
		for j := range outputs {
			outputs[j] = bound.Out(j)
		}
		out = append(out, MethodSignature{Name: method.Name, Inputs: inputs, Outputs: outputs})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

func nilCapable(kind reflect.Kind) bool {
	switch kind {
	case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map, reflect.Ptr, reflect.Slice, reflect.UnsafePointer:
		return true
	default:
		return false
	}
}

func Invoke(receiver any, method string, args []any) (results []any, err error) {
	value, err := receiverValue(receiver)
	if err != nil {
		return nil, err
	}
	if method == "" {
		return nil, fmt.Errorf("blank method name")
	}
	callable := value.MethodByName(method)
	if !callable.IsValid() {
		return nil, fmt.Errorf("method not found")
	}
	typ := callable.Type()
	if len(args) != typ.NumIn() {
		return nil, fmt.Errorf("wrong argument count")
	}
	values := make([]reflect.Value, len(args))
	for i, arg := range args {
		want := typ.In(i)
		if arg == nil {
			if !nilCapable(want.Kind()) {
				return nil, fmt.Errorf("argument %d cannot be nil", i)
			}
			values[i] = reflect.Zero(want)
			continue
		}
		got := reflect.ValueOf(arg)
		if !got.Type().AssignableTo(want) {
			return nil, fmt.Errorf("argument %d has incompatible type", i)
		}
		values[i] = got
	}
	defer func() {
		if recovered := recover(); recovered != nil {
			results = nil
			err = fmt.Errorf("method panicked: %v", recovered)
		}
	}()
	var returned []reflect.Value
	if typ.IsVariadic() {
		returned = callable.CallSlice(values)
	} else {
		returned = callable.Call(values)
	}
	results = make([]any, len(returned))
	for i, result := range returned {
		results[i] = result.Interface()
	}
	return results, nil
}
